二分查找 (Binary Search)
==========================
- 时间复杂度: O(log n)
- 空间复杂度: O(1) 迭代 / O(log n) 递归
- 前提条件: 数组必须已排序
- 特点: 效率极高，每次将搜索范围减半
"""


def binary_search_iterative(arr, target):
    """二分查找 - 迭代版"""
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2  # 防溢出写法
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1


def binary_search_recursive(arr, target, left=None, right=None):
    """二分查找 - 递归版"""
    if left is None:
        left, right = 0, len(arr) - 1
    if left > right:
        return -1
    mid = left + (right - left) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return binary_search_recursive(arr, target, mid + 1, right)
    else:
        return binary_search_recursive(arr, target, left, mid - 1)


def binary_search_leftmost(arr, target):
    """查找最左出现位置 (第一个等于 target 的索引)"""
    left, right = 0, len(arr) - 1
    result = -1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == target:
            result = mid
            right = mid - 1  # 继续往左找
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return result


def binary_search_rightmost(arr, target):
    """查找最右出现位置 (最后一个等于 target 的索引)"""
    left, right = 0, len(arr) - 1
    result = -1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == target:
            result = mid
            left = mid + 1  # 继续往右找
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return result


def binary_search_insert_pos(arr, target):
    """查找插入位置 (第一个 >= target 的索引)"""
    left, right = 0, len(arr)
    while left < right:
        mid = left + (right - left) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left


if __name__ == '__main__':
    data = [2, 3, 4, 10, 10, 10, 40, 50]

    print("=== 二分查找 ===")
    print(f"数据: {data}")
    print(f"迭代查找 10: 索引 = {binary_search_iterative(data, 10)}")
    print(f"递归查找 4:  索引 = {binary_search_recursive(data, 4)}")
    print(f"查找 100:    索引 = {binary_search_iterative(data, 100)}")
    print(f"最左 10:     索引 = {binary_search_leftmost(data, 10)}")
    print(f"最右 10:     索引 = {binary_search_rightmost(data, 10)}")
    print(f"插入位置 11: 索引 = {binary_search_insert_pos(data, 11)}")
    print(f"插入位置 1:  索引 = {binary_search_insert_pos(data, 1)}")
    print()
